<!-- wp:wdl/lw-step-1 {"bgGradient":"#2f3437","filterOpacity":0.08,"titleText":"\u003cspan data-lw_font_set=\u0022Shippori Mincho\u0022 class=\u0022custom-font-settings\u0022\u003e当日の流れ\u003c/span\u003e","ulMaxWidth":760,"fontH3":"Shippori Mincho","fontWeightH3":"500","colorLiSvg":"#a9884b"} -->
<div class="wp-block-wdl-lw-step-1 lw-step-1"><h2 class="lw-step-1__title"><span data-lw_font_set="Shippori Mincho" class="custom-font-settings">当日の流れ</span></h2><ul class="lw-step-1__inner" style="max-width:760px"><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">カウンセリング</h3><p data-lw_font_set="" style="font-weight:">毛の状態と肌質を見て、部位ごとの目安回数をお伝えします。無理におすすめすることはありません。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">テスト照射</h3><p data-lw_font_set="" style="font-weight:">初回は必ず狭い範囲で試します。赤みが出ないことを確かめてから進めます。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">施術</h3><p data-lw_font_set="" style="font-weight:">冷やしながら進めます。輪ゴムで軽く弾かれる程度とおっしゃる方が多い痛みですが、出力はその都度調整します。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li><li class="lw-step-1__li"><h3 data-lw_font_set="Shippori Mincho" style="font-weight:500;background:#2f3437">アフターケア</h3><p data-lw_font_set="" style="font-weight:">冷やして保湿します。次回の目安（4〜6週間後）をお伝えして終わりです。</p><span class="icon" style="fill:#a9884b"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512"><path d="M233.4 406.6c12.5 12.5 32.8 12.5 45.3 0l192-192c12.5-12.5 12.5-32.8 0-45.3s-32.8-12.5-45.3 0L256 338.7 86.6 169.4c-12.5-12.5-32.8-12.5-45.3 0s-12.5 32.8 0 45.3l192 192z"></path></svg></span></li></ul><div class="lw-step-1__filter" style="background:#2f3437;opacity:0.08"></div></div>
<!-- /wp:wdl/lw-step-1 -->

